static void em_modify_application_context(
    const rule_info_t *rule, int verdict, uint64_t timestamp,
    uint64_t counter, const mmt_array_t * const trace) {

    char original_context[22];
    int ret = get_dicom_attribute(701, 6, original_context);
    if (ret < 0) {
        log_info("Failed to get application context");
        forward_packet();
        return;
    }

    const char *invalid_context = "9.9.999.99999.9.9";
    replace_dicom_attribute(701, 6, invalid_context, 1);
    log_info("Modified application context to: %s", invalid_context);

    forward_packet();
}
